import { React, Fragment, useState, useEffect, useRef, useMemo } from "react";
import { trackPromise } from "react-promise-tracker";
import axios from "axios";
import ShowSpinner from "./ShowSpinner";

const ManageRequest = props => {
  const { userList, setDisplayAlert, convert2MMDDYY, setRefDetails } = props;

  const [racf, setRACF] = useState("");
  const [fullRefList, setFullRefList] = useState([]);
  const [selectedRef, setSelectedRef] = useState("");
  const [office, setOffice] = useState("N/A");
  const [entitledDays, setEntitledDay] = useState("N/A");
  const [leaveType, setLeaveType] = useState("N/A");
  const [refDate, setRefDate] = useState("N/A");
  const [periodStart, setPeriodStart] = useState("N/A");
  const [periodEnd, setPeriodEnd] = useState("N/A");
  const [accumulated, setAccumulated] = useState("N/A");
  const [excludedHolidays, setExcludedHolidays] = useState("N/A");
  const [status, setStatus] = useState("N/A");

  const [isCanceling, setIsCanceling] = useState(false);
  const [isOpen, setIsOpen] = useState(true);

  const [applicantSearch, setApplicantSearch] = useState("");
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [highlightedIndex, setHighlightedIndex] = useState(-1);
  const dropdownRef = useRef(null);

  const displayRefList = useMemo(() => {
    return racf
      ? fullRefList.filter(ref => ref.racf && ref.racf.toUpperCase() === racf.toUpperCase())
      : [];
  }, [racf, fullRefList]);

  const filteredUsers = useMemo(() => {
    return userList ? userList.filter(user => {
      const searchTerm = applicantSearch.toLowerCase();
      return (
        user.name.toLowerCase().includes(searchTerm) ||
        user.racf.toLowerCase().includes(searchTerm)
      );
    }).slice(0, 1000) : [];
  }, [userList, applicantSearch]);

  useEffect(() => {
    if (showSuggestions && highlightedIndex >= 0 && dropdownRef.current) {
      const items = dropdownRef.current.querySelectorAll('.suggestion-item');
      if (items[highlightedIndex]) {
        items[highlightedIndex].scrollIntoView({
          behavior: "smooth",
          block: "nearest"
        });
      }
    }
  }, [highlightedIndex, showSuggestions]);

  const selectApplicant = (user) => {
    setRACF(user.racf.toUpperCase());
    setApplicantSearch(`${user.name} (${user.racf})`);
    setShowSuggestions(false);
    setHighlightedIndex(-1);
    setSelectedRef("");
  };

  const handleApplicantSearch = (e) => {
    setApplicantSearch(e.target.value);
    setShowSuggestions(true);
    setHighlightedIndex(0);
    if (e.target.value === "") {
      setRACF("");
      setSelectedRef("");
    }
  };

  const handleKeyDown = (e) => {
    if (!showSuggestions || filteredUsers.length === 0) return;
    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        setHighlightedIndex(prev => prev < filteredUsers.length - 1 ? prev + 1 : 0);
        break;
      case "ArrowUp":
        e.preventDefault();
        setHighlightedIndex(prev => prev > 0 ? prev - 1 : filteredUsers.length - 1);
        break;
      case "Enter":
        e.preventDefault();
        if (highlightedIndex >= 0 && highlightedIndex < filteredUsers.length) {
          selectApplicant(filteredUsers[highlightedIndex]);
        }
        break;
      case "Escape":
        setShowSuggestions(false);
        setHighlightedIndex(-1);
        break;
      default:
        break;
    }
  };

  function handleRefNo(event) {
    const { value } = event.target;
    setSelectedRef(value);
  }

  useEffect(() => {
    trackPromise(
      axios({
        url: "/eleave/api/getAllSpecialRef",
        method: "GET",
      })
        .then(response => response.data)
        .then(data => {
          setFullRefList(data);
        }),
      "getAllRefListUpfront"
    );
  }, []);

  useEffect(() => {
    if (isCanceling) return;

    if (!selectedRef) {
      setOffice("N/A");
      setEntitledDay("N/A");
      setLeaveType("N/A");
      setStatus("N/A");
      setRefDate("N/A");
      setPeriodStart("N/A");
      setPeriodEnd("N/A");
      setAccumulated("N/A");
      setExcludedHolidays("N/A");
      return;
    }

    const selectedDetails = displayRefList.find(ref => ref.ref_no === selectedRef);

    if (selectedDetails) {
      setRefDetails(selectedDetails);
      setOffice(selectedDetails.office || "N/A");
      setEntitledDay(selectedDetails.entitled_days ? selectedDetails.entitled_days.toFixed(1) : "N/A");
      setLeaveType(selectedDetails.leave_type_name ? selectedDetails.leave_type_name : "N/A");
      setStatus(selectedDetails.status ? selectedDetails.status : "N/A");
      setRefDate(selectedDetails.ref_date ? selectedDetails.ref_date : "N/A");
      setPeriodStart(selectedDetails.period_start ? convert2MMDDYY(selectedDetails.period_start) : "N/A");
      setPeriodEnd(selectedDetails.period_end ? convert2MMDDYY(selectedDetails.period_end) : "N/A");
      setAccumulated(
        selectedDetails.accumulated === null || selectedDetails.accumulated === undefined
          ? "N/A"
          : selectedDetails.accumulated 
            ? "Yes" 
            : "No"
      );
      setExcludedHolidays(
        selectedDetails.excluded_holidays === null || selectedDetails.excluded_holidays === undefined
        ? "N/A"
        : selectedDetails.excluded_holidays
          ? "Exclusive"
          : "Inclusive"
      );
    }
  }, [selectedRef, displayRefList, convert2MMDDYY, setRefDetails, isCanceling]);

  const handleCancel = event => {
    if (!selectedRef) return;
    if (!window.confirm(`Are you sure you want to cancel ${selectedRef}?`)) {
      return null;
    }
    
    setIsCanceling(true);
    
    trackPromise(
      axios({
        url: "/eleave/api/cancelRequest",
        method: "POST",
        headers: { "Content-type": "application/json", api: "yes" },
        data: JSON.stringify({ 'ref_no': selectedRef, 'racf': racf })
      })
        .then(response => {
          setDisplayAlert({ message: "Requisition cancelled successfully ", position: 4, timeout: 10000, color: "alert__green" });
          
          setFullRefList(prevList => 
            prevList.map(ref => ref.ref_no === selectedRef ? { ...ref, status: 'Canceled' } : ref)
          );

          setIsCanceling(false);
        })
        .catch(error => {
          const errMsg = error.response?.data?.error_message || "An error occurred";
          setDisplayAlert({ message: errMsg, position: 4, timeout: 10000, color: "alert__red" });
          setIsCanceling(false);
        }),
      "cancelOtherLeave"
    );
  };

  const handleApprove = event => {
    if (!selectedRef) return;

    if (!window.confirm(`Are you sure you want to approve ${selectedRef}?`)) {
      return null;
    }

    setIsCanceling(true);

    trackPromise(
      axios({
        url: "/eleave/api/approveRequest",
        method: "POST",
        headers: { "Content-type": "application/json", api: "yes" },
        data: JSON.stringify({ 'ref_no': selectedRef})
      })
        .then(response => {
          setDisplayAlert({ message: "Requisition approved successfully ", position: 4, timeout: 10000, color: "alert__green" });
          
          setFullRefList(prevList => 
            prevList.map(ref => ref.ref_no === selectedRef ? { ...ref, status: 'Approved' } : ref)
          );

          setIsCanceling(false);
        })
        .catch(error => {
          const errMsg = error.response?.data?.error_message || "An error occurred";
          setDisplayAlert({ message: errMsg, position: 4, timeout: 10000, color: "alert__red" });
          setIsCanceling(false);
        }),
      "approveOtherLeave"
    );
  };

  const handleReject = event => {
    if (!selectedRef) return;
    if (!window.confirm(`Are you sure you want to reject ${selectedRef}?`)) {
      return null;
    }

    setIsCanceling(true);

    trackPromise(
      axios({
        url: "/eleave/api/rejectRequest",
        method: "POST",
        headers: { "Content-type": "application/json", api: "yes" },
        data: JSON.stringify({ 'ref_no': selectedRef})
      })
        .then(response => {
          setDisplayAlert({ message: "Requisition rejected successfully ", position: 4, timeout: 10000, color: "alert__green" });
          
          setFullRefList(prevList => 
            prevList.map(ref => ref.ref_no === selectedRef ? { ...ref, status: 'Rejected' } : ref)
          );

          setIsCanceling(false);
        })
        .catch(error => {
          const errMsg = error.response?.data?.error_message || "An error occurred";
          setDisplayAlert({ message: errMsg, position: 4, timeout: 10000, color: "alert__red" });
          setIsCanceling(false);
        }),
      "rejectOtherLeave"
    );

  };

  const statusClasses = {
    Canceled: 'status-canceled',
    Pending: 'status-pending',
    Approved: 'status-approved',
    Rejected: 'status-canceled'
  };

  const currentStatusClass = statusClasses[status] || '';

  return (
    <Fragment>
      <ShowSpinner position={6} />
      <div>
        <div className="separator separator-flex">
          <span>Reference Management</span>
          <button 
            className="toggle-btn"
            onClick={() => setIsOpen(!isOpen)}
          >
            {isOpen ? "-" : "+"}
          </button>
        </div>
        
        {isOpen && (
          <>
            <div className="managerequest_type_grid">
              <div className="managerequest_type_area_a managerequest_type_grid_a">
                Applicant:
                <div className="relative-inline-block">
                  <input
                    type="text"
                    className="applicant-input-large"
                    value={applicantSearch}
                    onChange={handleApplicantSearch}
                    onKeyDown={handleKeyDown}
                    onFocus={() => setShowSuggestions(true)}
                    onBlur={() => setTimeout(() => setShowSuggestions(false), 200)}
                    placeholder="Search name or RACF..."
                    autoComplete="off"
                  />
                  {showSuggestions && filteredUsers.length > 0 && (
                    <div
                      ref={dropdownRef}
                      className="suggestions-dropdown-large"
                    >
                      {filteredUsers.map((user, index) => (
                        <div
                          key={index}
                          className={`suggestion-item ${index === highlightedIndex ? 'highlighted' : ''}`}
                          onClick={() => selectApplicant(user)}
                          onMouseDown={(e) => e.preventDefault()}
                        >
                          {user.name} ({user.racf})
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
              <div className="managerequest_type_area_b managerequest_type_grid_b">
                Approval #:
                <select className="select-large clickable" onChange={handleRefNo} id="specialLeave_select" value={selectedRef}>
                  <option value="" disabled> - </option>
                  {displayRefList.map((ref) => (<option key={ref.ref_no} value={ref.ref_no}> {ref.ref_no}</option>))}
                </select>
              </div>
              <div className="managerequest_type_area_c managerequest_type_grid_c leave-details-header">
                <div><strong>Leave Details</strong></div>
              </div>
              <div className="managerequest_type_area_d managerequest_type_grid_d">
                Office : {office}
              </div>
              <div className={`managerequest_type_area_l managerequest_type_grid_l ${currentStatusClass}`}>
                Status : {status}
              </div>
              <div className="managerequest_type_area_e managerequest_type_grid_e">
                Entitled Days : {entitledDays}
              </div>
              <div className="managerequest_type_area_f managerequest_type_grid_f">
                Leave Type : {leaveType}
              </div>
              <div className="managerequest_type_area_g managerequest_type_grid_g">
                Ref Date: {refDate}
              </div>
              <div className="managerequest_type_area_h managerequest_type_grid_h">
                Period Start: {periodStart}
              </div>
              <div className="managerequest_type_area_i managerequest_type_grid_i">
                Period End: {periodEnd}
              </div>
              <div className="managerequest_type_area_j managerequest_type_grid_j">
                Accumulated: {accumulated}
              </div>
              <div className="managerequest_type_area_k managerequest_type_grid_k">
                Excluded Holidays: {excludedHolidays}
              </div>
            </div>
            
            {status === "Pending" && (
              <div className="action_button_group">
                <button id="approve_button" onClick={handleApprove}>
                  Approve
                </button>
                <button id="reject_button" onClick={handleReject}>
                  Reject
                </button>
              </div>
            )}

            {status === "Approved" && (
              <button id="managerequest_button" onClick={handleCancel}>
                Cancel
              </button>
            )}

            <div className="managerequest_keepbottomline"></div>
          </>
        )}
      </div>
    </Fragment>
  );
};

export default ManageRequest;