import React, { Fragment, useState, useRef, useEffect } from "react";
import { trackPromise } from "react-promise-tracker";
import axios from "axios";
import DatePicker from 'react-datepicker';
import ShowSpinner from "./ShowSpinner";

const EnterRequest = props => {
  const { office, leaveType, setDisplayAlert, userList } = props;

  const [entitledDay, setEntitledDay] = useState("");
  const [racf, setRACF] = useState("");
  const [applicantSearch, setApplicantSearch] = useState("");
  const [newRefNo, setNewRefno] = useState("");
  const [accumulated, setAccumulated] = useState("True");
  const [exclusive, setExclusive] = useState("True");
  const [selectedOfc, setSelectedOfc] = useState("");
  const [selectedType, setSelectedType] = useState("");
  const [refDate, setRefDate] = useState("");
  const [periodStart, setperiodStart] = useState("");
  const [periodEnd, setperiodEnd] = useState("");
  const [attachments, setAttachments] = useState([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [highlightedIndex, setHighlightedIndex] = useState(-1);
  const [submitted, setSubmitted] = useState(false);
  const [isOpen, setIsOpen] = useState(true);
  
  const dropdownRef = useRef(null);
  const fileInputRef = useRef(null);

  const currentDate = new Date();
  const year = currentDate.getFullYear();

  const filteredUsers = userList ? userList.filter(user => {
    const searchTerm = applicantSearch.toLowerCase();
    return (
      user.name.toLowerCase().includes(searchTerm) ||
      user.racf.toLowerCase().includes(searchTerm)
    );
  }).slice(0, 1000) : [];

  useEffect(() => {
    if (showSuggestions && highlightedIndex >= 0 && dropdownRef.current) {
      const items = dropdownRef.current.querySelectorAll('.suggestion-item');
      if (items[highlightedIndex]) {
        items[highlightedIndex].scrollIntoView({
          behavior: "smooth",
          block: "nearest"
        });
      }
    }
  }, [highlightedIndex, showSuggestions]);

  const dateToString = (date, pos) => {
    if (!date) {
      if (pos === 1) setRefDate("");
      if (pos === 2) {
        setperiodStart("");
        setperiodEnd("");
      }
      if (pos === 3) setperiodEnd("");
      return;
    }
    const userTimezoneOffset = date.getTimezoneOffset() * 60000;
    const d = new Date(date.getTime() - userTimezoneOffset);

    if (pos === 1) setRefDate(d.toISOString().substring(0, 10));
    if (pos === 2) {
      setperiodStart(d.toISOString().substring(0, 10));
      setperiodEnd(d.toISOString().substring(0, 10));
    }
    if (pos === 3) setperiodEnd(d.toISOString().substring(0, 10));
  };

  const stringToDate = dateString => {
    if (dateString === "") return null;
    const d = new Date(dateString);
    const userTimezoneOffset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() + userTimezoneOffset);
  };

  const handleOffice = event => {
    const { value } = event.target;
    setSelectedOfc(value);
  };

  const handleAccumulated = event => {
    const { value } = event.target;
    setAccumulated(value);
  };

  const handleExclusive = event => {
    const { value } = event.target;
    setExclusive(value);
  };

  const handleLeaveType = event => {
    setSelectedType(event.target.value);
  };

  const handleRefDate = event => {
    setRefDate(event.target.value);
  };

  const handleEntitledDay = event => {
    setEntitledDay(event.target.value);
  };

  const handleAttachment = event => {
    const selectedFiles = Array.from(event.target.files);
    setAttachments(prev => [...prev, ...selectedFiles]);
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const removeFile = (indexToRemove) => {
    setAttachments(prev => prev.filter((_, index) => index !== indexToRemove));
  };

  const clearAttachments = () => {
    setAttachments([]);
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const selectApplicant = (user) => {
    setRACF(user.racf);
    setApplicantSearch(`${user.name} (${user.racf})`);
    setShowSuggestions(false);
    setHighlightedIndex(-1);
  };

  const handleApplicantSearch = (e) => {
    setApplicantSearch(e.target.value);
    setShowSuggestions(true);
    setHighlightedIndex(0);
    if (e.target.value === "") {
      setRACF("");
    }
  };

  const handleKeyDown = (e) => {
    if (!showSuggestions || filteredUsers.length === 0) return;

    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        setHighlightedIndex(prev => prev < filteredUsers.length - 1 ? prev + 1 : 0);
        break;
      case "ArrowUp":
        e.preventDefault();
        setHighlightedIndex(prev => prev > 0 ? prev - 1 : filteredUsers.length - 1);
        break;
      case "Enter":
        e.preventDefault();
        if (highlightedIndex >= 0 && highlightedIndex < filteredUsers.length) {
          selectApplicant(filteredUsers[highlightedIndex]);
        }
        break;
      case "Escape":
        setShowSuggestions(false);
        setHighlightedIndex(-1);
        break;
      default:
        break;
    }
  };

  const otherleave = Object.values(leaveType).map((item) => ({
    value: item.leave_type_id,
    label: item.leave_type,
  }));

  const handleSubmit = async () => {
    if (!selectedOfc) {
      setDisplayAlert({ message: "Please select Office", position: 4, timeout: 5000, color: "alert__red" });
      return;
    }

    if (!racf || !selectedType || !entitledDay) {
      setDisplayAlert({ message: "Please fill in all required fields", position: 4, timeout: 5000, color: "alert__red" });
      return;
    }

    if (!window.confirm('Are you sure you want to submit?')) return;

    try {
      const refResponse = await trackPromise(
        axios({
          url: "/eleave/api/specialLeaveRefNo",
          method: "POST",
          headers: { "Content-type": "application/json", api: "yes" },
          data: JSON.stringify({ Office: selectedOfc, Year: year })
        }),
        "getNewRefno"
      );

      const generatedRefNo = refResponse.data;

      const formData = new FormData();
      formData.append("office", selectedOfc);
      formData.append("racf", racf);
      formData.append("year", year);
      formData.append("ref_no", generatedRefNo);
      formData.append("leave_type", selectedType);
      formData.append("entitled_days", entitledDay);
      formData.append("ref_date", refDate);
      formData.append("period_start", periodStart);
      formData.append("period_end", periodEnd);
      formData.append("accumulated", accumulated);
      formData.append("excluded_holidays", exclusive);
      
      if (attachments.length > 0) {
        attachments.forEach(file => {
          formData.append("attachment", file);
        });
      }

      await trackPromise(
        axios({
          url: "/eleave/api/submitRequest",
          method: "POST",
          headers: { api: "yes" },
          data: formData
        }),
        "otherLeave"
      );

      setNewRefno(generatedRefNo);
      setSubmitted(true);

      setDisplayAlert({ 
        message: `Requisition submitted successfully. Approval #: ${generatedRefNo}`, 
        position: 4, 
        timeout: 10000, 
        color: "alert__green" 
      });

    } catch (error) {
      setNewRefno("");
      
      const msg = error.response?.data?.error_message || "Submit failed";
      setDisplayAlert({ 
        message: msg, 
        position: 4, 
        timeout: 10000, 
        color: "alert__red" 
      });
    }
  };

  const clearAll = () => {
    setAccumulated("True");
    setExclusive("True");
    setSelectedOfc("");
    setRACF("");
    setApplicantSearch("");
    setSelectedType("");
    setEntitledDay("");
    setRefDate("");
    setperiodStart("");
    setperiodEnd("");
    setNewRefno("");
    clearAttachments();
    setShowSuggestions(false);
    setHighlightedIndex(-1);
    setSubmitted(false);
  };

  return (
    <Fragment>
      <div className="request-container">
        <div className="separator separator-flex">
          <span>Submit Reference</span>
          <button 
            className="toggle-btn"
            onClick={() => setIsOpen(!isOpen)}
          >
            {isOpen ? "-" : "+"}
          </button>
        </div>

        {isOpen && (
          <>
            <div className="sp_type_grid">
              <div className="sp_type_area_a sp_type_grid_a">
                Office:
                <select 
                  className="select-small"
                  onChange={handleOffice} 
                  value={selectedOfc}
                >
                  <option value="" disabled>-</option>
                  {office.map((ofc) => (
                    <option key={ofc} value={ofc}>{ofc}</option>
                  ))}
                </select>
              </div>

              <div className="sp_type_area_b sp_type_grid_b">
                Applicant:
                <div className="relative-width-100">
                  <input
                    type="text"
                    className="applicant-search-input"
                    value={applicantSearch}
                    onChange={handleApplicantSearch}
                    onKeyDown={handleKeyDown}
                    onFocus={() => setShowSuggestions(true)}
                    onBlur={() => setTimeout(() => setShowSuggestions(false), 200)}
                    placeholder="Search name or RACF..."
                  />

                  {showSuggestions && filteredUsers.length > 0 && (
                    <div ref={dropdownRef} className="suggestions-dropdown">
                      {filteredUsers.map((user, index) => (
                        <div
                          key={index}
                          className={`suggestion-item ${index === highlightedIndex ? 'highlighted' : ''}`}
                          onClick={() => selectApplicant(user)}
                          onMouseDown={(e) => e.preventDefault()}
                        >
                          {user.name} ({user.racf})
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              <div className="sp_type_area_d sp_type_grid_d">
                Leave Type:
                <select value={selectedType} onChange={handleLeaveType}>
                  <option value="" disabled>-</option>
                  {otherleave.map((lve) => (
                    <option key={lve.value} value={lve.value}>
                      {lve.label}
                    </option>
                  ))}
                </select>
              </div>

              <div className="sp_type_area_e sp_type_grid_e">
                Entitled Days:
                <input 
                  type="number" 
                  min={0.5} 
                  max={999} 
                  step={0.5} 
                  id="specialLeave_number"
                  onChange={handleEntitledDay} 
                  value={entitledDay}
                />
              </div>

              <div className="sp_type_area_f sp_type_grid_f">
                Ref Date:
                <input 
                  type="text" 
                  id="specialLeave_input"
                  onChange={handleRefDate} 
                  value={refDate}
                />
              </div>

              <div className="sp_type_area_g sp_type_grid_g">
                Period Start:
                <DatePicker
                  portalId="datePicker"
                  selected={stringToDate(periodStart)}
                  onChange={date => dateToString(date, 2)}
                  dateFormat="MM/dd/yyyy"
                  placeholderText='Click to select a date'
                  className="custom-datepicker"
                />
              </div>

              <div className="sp_type_area_h sp_type_grid_h">
                Period End:
                <DatePicker
                  portalId="datePicker"
                  selected={stringToDate(periodEnd)}
                  onChange={date => dateToString(date, 3)}
                  dateFormat="MM/dd/yyyy"
                  placeholderText='Click to select a date'
                  className="custom-datepicker"
                />
              </div>

              <div className="sp_type_area_i sp_type_grid_i">
                Accumulated:
                <div className="flex-col-start">
                  <select 
                    className="select-small"
                    onChange={handleAccumulated} 
                    value={accumulated}
                  >
                    <option value="True">Yes</option>
                    <option value="False">No</option>
                  </select>
                  <span className="hint-text">
                    Can the request ticket be applied multiple times?
                  </span>
                </div>
              </div>

              <div className="sp_type_area_j sp_type_grid_j">
                Holiday/Weekend:
                <div className="flex-col-start">
                  <select 
                    className="select-medium"
                    onChange={handleExclusive} 
                    value={exclusive}
                  >
                    <option value="True">Exclusive</option>
                    <option value="False">Inclusive</option>
                  </select>
                  <span className="hint-text">
                    Does this request ticket's entitled days include weekends and public holidays?
                  </span>
                </div>
              </div>

              <div className="sp_type_area_k sp_type_grid_k">
                <div className="attachment-label">Attachment:</div>
                <div className="attachment-wrapper">
                  <div className="file-actions-col">
                    <label className="custom-file-upload">
                      <input 
                        type="file" 
                        className="hidden-file-input"
                        onChange={handleAttachment}
                        ref={fileInputRef}
                        multiple
                      />
                      Choose Files
                    </label>
                    <button 
                      type="button" 
                      className="clear-files-btn" 
                      onClick={clearAttachments}
                      disabled={attachments.length === 0}
                    >
                      Clear Files
                    </button>
                  </div>
                  
                  <div className="file-list-area">
                    {attachments.map((file, index) => (
                      <div key={index} className="file-list-item">
                        <span className="file-name" title={file.name}>{file.name}</span>
                        <button 
                          type="button" 
                          className="remove-file-btn" 
                          onClick={() => removeFile(index)}
                        >
                          ×
                        </button>
                      </div>
                    ))}
                    {Array.from({ length: Math.max(0, 3 - attachments.length) }).map((_, index) => (
                      <div key={`empty-${index}`} className="file-list-item empty-slot"></div>
                    ))}
                  </div>
                </div>
              </div>

              <div className="sp_type_area_c sp_type_grid_c">
                Approval #:
                <input 
                  value={newRefNo} 
                  disabled 
                  placeholder="Will be assigned on submit"
                />
              </div>
            </div>

            <button 
              id="specialLeave_submit" 
              onClick={handleSubmit}
              disabled={submitted}
              className={submitted ? "submit-btn-disabled" : ""}
            >
              Submit
            </button>
            <button id="specialLeave_clear" onClick={clearAll}>
              Clear
            </button>
          </>
        )}
      </div>

      <ShowSpinner position={5} />
    </Fragment>
  );
};

export default EnterRequest;